import{_ as o,a0 as n,w as r,s as d,ao as p,I as a,x as t,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"從實際代碼開始編寫好的示例 | LCTT x X-CMD","titleTemplate":false,"description":"從實際代碼開始編寫好的示例 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"從實際代碼開始編寫好的示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"從實際代碼開始編寫好的示例 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210708 Write good examples by starting with real code","title":"從實際代碼開始編寫好的示例","tag":"202107","desc":""},"relativePath":"202107/20210708 Write good examples by starting with real code.md","filePath":"[post].md"}'),u={name:"202107/20210708 Write good examples by starting with real code.md"};function m(b,e,h,g,k,f){const s=n("Link");return r(),d("div",null,[e[18]||(e[18]=p(`<h1 id="從實際代碼開始編寫好的示例" tabindex="-1">從實際代碼開始編寫好的示例 <a class="header-anchor" href="#從實際代碼開始編寫好的示例" aria-label="Permalink to “從實際代碼開始編寫好的示例”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/18/231616z1hhcerhrk3wzwkr.jpg" alt=""></p><p>當編寫程序時，我花費了大量時間在編寫好的示例上。我從未見過有人寫過關於如何寫出好的示例，所以我就寫了一下如何寫出一份好的示例。</p><p>基礎思路就是從你寫的真實代碼開始，然後刪除不相關的細節，使其成為一個獨立的例子，而不是無中生有地想出一些例子。</p><p>我將會談論兩種示例：基於真實案例的示例和奇怪的示例</p><h3 id="好的示例是真實的" tabindex="-1">好的示例是真實的 <a class="header-anchor" href="#好的示例是真實的" aria-label="Permalink to “好的示例是真實的”">​</a></h3><p>為了説明為什麼好的案例應該是真實的，我們就先討論一個不真實的案例。假設我們在試圖解釋 Python 的 lambda 函數（這只是我想到的第一個概念）。你可以舉一個例子，使用 <code>map</code> 和 lambda 來讓一組數字變為原先的兩倍。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>numbers = [1, 2, 3, 4]</span></span>
<span class="line"><span>squares = map(lambda x: x * x, numbers)</span></span></code></pre></div><p>我覺得這個示例不是真實的，有如下兩方面的原因：</p><ul><li>將一組數字作平方運算不是在真實的程序中完成的事，除非是歐拉項目或某種東西（更多的可能是針對列表的操作）</li><li><code>map</code> 在 Python 中並不常用，即便是做這個我也更願意寫 <code>[x*x for x in numbers]</code></li></ul><p>一個更加真實的 Python lambdas 的示例是使用 <code>sort</code> 函數，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>children = [{&quot;name&quot;: &quot;ashwin&quot;, &quot;age&quot;: 12}, {&quot;name&quot;: &quot;radhika&quot;, &quot;age&quot;: 3}]</span></span>
<span class="line"><span>sorted_children = sorted(children, key=lambda x: x[&#39;age&#39;])</span></span></code></pre></div><p>但是這個示例是被精心設計的（為什麼我們需要對這些孩子按照年齡進行排序呢？）。所以我們如何來做一個真實的示例呢？</p><h3 id="如何讓你的示例真實起來-看你所寫實際代碼" tabindex="-1">如何讓你的示例真實起來：看你所寫實際代碼 <a class="header-anchor" href="#如何讓你的示例真實起來-看你所寫實際代碼" aria-label="Permalink to “如何讓你的示例真實起來：看你所寫實際代碼”">​</a></h3><p>我認為最簡單的來生成一個例子的方法就是，不是憑空出現一個例子（就像我用那個<code>兒童</code>的例子），而只是從真正的代碼開始！</p><p>舉一個例子吧，如果我要用 <code>sort.+key</code> 來編寫一串 Python 代碼，我會發現很多我按某個標準對列表進行排序的真實例子，例如：</p><ul><li><code>tasks.sort(key=lambda task: task[&#39;completed_time&#39;])</code></li><li><code>emails = reversed(sorted(emails, key=lambda x:x[&#39;receivedAt&#39;]))</code></li><li><code>sorted_keysizes = sorted(scores.keys(), key=scores.get)</code></li><li><code>shows = sorted(dates[date], key=lambda x: x[&#39;time&#39;][&#39;performanceTime&#39;])</code></li></ul><p>在這裏很容易看到一個規律——這些基本是按時間排序的！因此，你可以明白如何將按時間排序的某些對象（電子郵件、事件等）的簡單實例輕鬆地放在一起。</p><h3 id="現實的例子有助於-佈道-你試圖解釋的概念" tabindex="-1">現實的例子有助於“佈道”你試圖解釋的概念 <a class="header-anchor" href="#現實的例子有助於-佈道-你試圖解釋的概念" aria-label="Permalink to “現實的例子有助於“佈道”你試圖解釋的概念”">​</a></h3><p>當我試圖去解釋一個想法（就好比 Python Lambdas）的時候，我通常也會試圖説服讀者，説這是值得學習的想法。Python lambdas 是如此的有用！當我去試圖説服某個人 lambdas 是很好用的時候，讓他想像一下 lambdas 如何幫助他們完成一項他們將要去做的任務或是以及一項他們以前做過的任務，對説服他會很有幫助。</p><h3 id="從真實代碼中提煉出示例可能需要很長時間" tabindex="-1">從真實代碼中提煉出示例可能需要很長時間 <a class="header-anchor" href="#從真實代碼中提煉出示例可能需要很長時間" aria-label="Permalink to “從真實代碼中提煉出示例可能需要很長時間”">​</a></h3><p>我給出如何使用 <code>lambda</code> 和 <code>sort</code> 函數的解釋例子是十分簡單的，它並不需要花費我很長時間來想出來，但是將真實的代碼提煉出為一個獨立的示例則是會需要花費很長的時間！</p><p>舉個例子，我想在這篇文章中融入一些奇怪的 CSS 行為的例子來説明創造一個奇怪的案例是十分有趣的。我花費了兩個小時來解決我這周遇到的一個實際的問題，確保我理解 CSS 的實際情況，並將其變成一個小示例。</p>`,23)),a("p",null,[e[1]||(e[1]=t("最後，它“僅僅”用了 ",-1)),l(s,{href:"https://codepen.io/wizardzines/pen/0eda7725a46c919dcfdd3fa80aff3d41"},{default:i(()=>[...e[0]||(e[0]=[t("五行 HTML 和一點點的 CSS",-1)])]),_:1}),e[2]||(e[2]=t(" 來説明了這個問題，看起來並不想是我花費了好多小時寫出來的。但是最初它卻是幾百行的 JS/CSS/JavaScript，它需要花費很長時間來將所有的代碼化為核心的很少的代碼。",-1))]),e[19]||(e[19]=a("p",null,"但我認為花點時間把示例講得非常簡單明瞭是值得的——如果有成百上千的人在讀你的示例，你就節省了他們這麼多時間！",-1)),e[20]||(e[20]=a("h3",{id:"就這麼多了",tabindex:"-1"},[t("就這麼多了！ "),a("a",{class:"header-anchor",href:"#就這麼多了","aria-label":"Permalink to “就這麼多了！”"},"​")],-1)),e[21]||(e[21]=a("p",null,"我覺得還有更多關於示例可以去講的——幾種不同類型的有用示例，例如：",-1)),e[22]||(e[22]=a("ul",null,[a("li",null,"可以更多的改變人的思維而不是直接提供使用的驚喜讀者的示例代碼"),a("li",null,"易於複製粘貼以用作初始化的示例")],-1)),e[23]||(e[23]=a("p",null,"也許有一天我還會再寫一些呢？ 😃",-1)),e[24]||(e[24]=a("hr",null,null,-1)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),l(s,{href:"https://jvns.ca/blog/2021/07/08/writing-great-examples/"},{default:i(()=>[...e[3]||(e[3]=[t("https://jvns.ca/blog/2021/07/08/writing-great-examples/",-1)])]),_:1})]),a("p",null,[e[9]||(e[9]=t("作者：",-1)),l(s,{href:"https://jvns.ca/"},{default:i(()=>[...e[5]||(e[5]=[t("Julia Evans",-1)])]),_:1}),e[10]||(e[10]=t(" 選題：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[6]||(e[6]=[t("lujun9972",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),l(s,{href:"https://github.com/zepoch"},{default:i(()=>[...e[7]||(e[7]=[t("zepoch",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),l(s,{href:"https://github.com/turbokernel"},{default:i(()=>[...e[8]||(e[8]=[t("turbokernel",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:i(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const C=o(u,[["render",m]]);export{y as __pageData,C as default};
